import type { ErrorCategory } from '../types'

export type ErrorDescription = { category: ErrorCategory; fingerprint: string; message: string }

/** Strips instance URLs and 32-char hex sys_ids from a message so nothing sensitive is transmitted. */
export function sanitizeErrorMessage(message: string): string {
    return message.replace(/https?:\/\/[^\s]+/g, '<url>').replace(/[a-f0-9]{32}/gi, '<sys_id>')
}

/** Normalizes an unknown error into a sanitized, categorized description shared by all telemetry clients. */
export function describeError(error: unknown): ErrorDescription {
    const raw = error instanceof Error ? error.message : String(error)
    const message = sanitizeErrorMessage(raw)
    return { category: categorizeError(message), fingerprint: message, message }
}

// Ordered by precedence — the first category with a matching keyword wins.
const ERROR_CATEGORY_KEYWORDS: [ErrorCategory, string[]][] = [
    ['auth', ['credential', 'auth', 'login', 'unauthorized']],
    ['network', ['network', 'fetch', 'timeout', 'econnrefused']],
    ['validation', ['validation', 'invalid', 'required']],
    ['build', ['build']],
    ['transform', ['transform']],
    ['install', ['install']],
    ['download', ['download']],
    ['config', ['config']],
]

function categorizeError(message: string): ErrorCategory {
    const lower = message.toLowerCase()
    return ERROR_CATEGORY_KEYWORDS.find(([, keywords]) => keywords.some((k) => lower.includes(k)))?.[0] ?? 'unknown'
}
